  preferred_language_raw: raw.question_lylEgW?.value || raw.question_lylEgW || '🇺🇸 English',

  // ID unique pour la liaison (Utilise l'ID de soumission Tally + Email pour sécurité totale)
  client_id: raw.id || (String(raw.question_J6DPKo?.value || 'unknown').toLowerCase().replace('@', '_at_') + '_' + Date.now()),
  respondent_id: raw.respondentId || 'unknown'
};

// 3. Nettoyage basique
const firstName = String(formData.firstName).trim();
const email = String(formData.email).trim().toLowerCase();

// 4. VALIDATION
if (!firstName || firstName.length < 2) {
  throw new Error('❌ First name is required and must be at least 2 characters');
}
if (!email || !email.includes('@')) {
  throw new Error('❌ Valid email is required');
}

// 5. LEAD SCORING
const budgetStr = String(formData.marketingBudget).toLowerCase();
let price_usd = 0;

if (budgetStr.includes('20')) price_usd = 19700;
else if (budgetStr.includes('10')) price_usd = 9700;
else if (budgetStr.includes('5')) price_usd = 4900;
else price_usd = 2900;

if (!price_usd || price_usd < 2900) {
  throw new Error('❌ Invalid price calculation - blocking checkout');
}

// 6. SEGMENTATION
let segment = 'starter';
if (price_usd >= 19700) segment = 'premium';
else if (price_usd >= 9700) segment = 'standard';

// 7. MAPPING DE LA LANGUE
const languageMap = {
  '🇺🇸 English': 'en',
  '🇫🇷 Français': 'fr',
  '🇪🇸 Español': 'es',
  '🇩🇪 Deutsch': 'de'
};

const preferredLang = languageMap[formData.preferred_language_raw] || 'en';

// 8. OUTPUT
return {
  json: {
    ...formData,
    preferred_language: preferredLang, // 'en', 'fr', 'es' ou 'de'
    price_usd,
    segment,
    processedAt: new Date().toISOString()
  }
};

